M1_W=cut('<section id="m1-calc">','</section>').replace('Loading inputs…',f'Stored example ({F["date"]}): at 30% backing, M1 {F["m1t"]} ({F["m2m"]}, FRED M1SL) gives about {F["m1g"]}/oz gold and {F["m1s"]}/oz silver.')
